1	/**
2	 * @module features/tv-dashboard/model/useTvDashboardData
3	 *
4	 * Hook principal da Torre de Controle da Operação (painel TV `/tv`).
5	 *
6	 * Paraleliza as fontes de dados via React Query:
7	 * - vendas live (edge `degust-pos-financial`/flash-vendas) — polling 60s;
8	 * - vendas defasadas Linx (`historico_vendas`, último dia disponível);
9	 * - comparativos: vs DIA ANTERIOR (principal, v3 — base pró-rateada p/ canal
10	 *   live) e vs MESMO DIA da semana passada (secundário);
11	 * - metas por loja × dia da semana (`metas_vendas`) com pró-rata da janela;
12	 * - alertas de estoque NOMEADOS (`estoque` × `produtos_master.ativo = true`,
13	 *   restritos ao setor de produtos vendáveis — `TV_ALERT_SETOR`);
14	 * - heartbeat + FEED nomeado de movimentações (`movimentacoes` de hoje);
15	 * - perdas no período do filtro global (`perdas`, R$ + itens + delta);
16	 * - compras no período (`notas_fiscais`, "gasto até hoje" + delta);
17	 * - produção da fábrica (`daily_production` com loja_id NULL).
18	 *
19	 * Nenhum `loja_id` é hardcoded: os canais são derivados em runtime de
20	 * `lojas` + `degust_stores` (Degust = live; demais lojas ativas = Linx
21	 * defasado; tipo "Fabrica" = card de fábrica).
22	 */
23	
24	import { useMemo } from 'react';
25	import { useQuery } from '@tanstack/react-query';
26	import { supabase } from '@/integrations/supabase/client';
27	import type {
28	  TvDateRange,
29	  TvException,
30	  TvFactoryData,
31	  TvFactoryProduction,
32	  TvFreshness,
33	  TvMarketingSummary,
34	  TvMovementSummary,
35	  TvNetworkSummary,
36	  TvPerdasSummary,
37	  TvPeriod,
38	  TvRecentMove,
39	  TvSalesChannel,
40	  TvSalesSnapshot,
41	  TvStoreData,
42	  TvExceptionsResult,
43	} from './types';
44	import {
45	  FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
46	  TV_FACTORY_HOURS,
47	  TV_MINI_FEED_SIZE,
48	  addDays,
49	  aggregateMarketing,
50	  aggregateMovements,
51	  aggregatePerdas,
52	  businessDayFraction,
53	  buildFreshness,
54	  buildNoMovementException,
55	  buildRecentMoves,
56	  buildStockExceptions,
57	  buildStockSummary,
58	  classifyStoreRag,
59	  fetchAllPages,
60	  parseBrDateTime,
61	  parseIsoDateLocal,
62	  pctOfFullDayTarget,
63	  pctOfProRataTarget,
64	  periodRange,
65	  previousPeriodRange,
66	  proRataDayBase,
67	  rangeToLocalDayBounds,
68	  relativeDelta,
69	  remapFlashLojaIds,
70	  sortAndLimitExceptions,
71	  sortCriticalItems,
72	  toIsoDateLocal,
73	  weekOverWeekDelta,
74	  type FlashRow,
75	  type MarketingAggregate,
76	  type MarketingByLoja,
77	  type MovementAggregate,
78	  type MovementFeedRow,
79	  type PerdasAggregate,
80	  type PerdasByLoja,
81	  type StockDetail,
82	  type StockRow,
83	} from './tvMath';
84	import { useMinuteClock } from './useMinuteClock';
85	
86	// ─────────────────────────────────────────────────────────────────────────────
87	// Query keys + intervalos (exportados para o useTvRealtime invalidar)
88	// ─────────────────────────────────────────────────────────────────────────────
89	
90	/** Query keys do painel TV — usar SEMPRE estas referências para invalidar. */
91	export const tvDashboardKeys = {
92	  all: ['tv-dashboard'] as const,
93	  context: () => [...tvDashboardKeys.all, 'context'] as const,
94	  liveSales: () => [...tvDashboardKeys.all, 'live-sales'] as const,
95	  laggedSales: () => [...tvDashboardKeys.all, 'lagged-sales'] as const,
96	  /** Vendas de referência Degust (ontem + mesmo dia da semana passada). */
97	  referenceSales: () => [...tvDashboardKeys.all, 'reference-sales'] as const,
98	  metas: () => [...tvDashboardKeys.all, 'metas'] as const,
99	  stock: () => [...tvDashboardKeys.all, 'stock'] as const,
100	  movements: () => [...tvDashboardKeys.all, 'movements'] as const,
101	  /** Feed nomeado de movimentações de hoje (mini-feed "AGORA"). */
102	  movementFeed: () => [...tvDashboardKeys.all, 'movement-feed'] as const,
103	  /** Prefixo das perdas (invalidar TODOS os períodos de uma vez). */
104	  perdasRoot: () => [...tvDashboardKeys.all, 'perdas'] as const,
105	  perdas: (period: TvPeriod) => [...tvDashboardKeys.perdasRoot(), period] as const,
106	  /** Prefixo do marketing (invalidar TODOS os períodos de uma vez). */
107	  marketingRoot: () => [...tvDashboardKeys.all, 'marketing'] as const,
108	  marketing: (period: TvPeriod) => [...tvDashboardKeys.marketingRoot(), period] as const,
109	  factoryProduction: () => [...tvDashboardKeys.all, 'factory-production'] as const,
110	  /** Prefixo do drill-down por loja (invalidar todas as lojas/ranges). */
111	  storeDetailRoot: () => [...tvDashboardKeys.all, 'store-detail'] as const,
112	  storeDetail: (lojaId: number, range: TvDateRange) =>
113	    [...tvDashboardKeys.storeDetailRoot(), lojaId, range.from, range.to] as const,
114	};
115	
116	/** Intervalos de atualização (ms) por classe de dado. */
117	export const TV_QUERY_INTERVALS = {
118	  /** Vendas live: polling 60s (acceptance: atualização em até 60s). */
119	  liveMs: 60_000,
120	  /** Estoque/metas/movimentações/produção: 5min (+ Realtime invalida antes). */
121	  slowMs: 300_000,
122	} as const;
123	
124	// ─────────────────────────────────────────────────────────────────────────────
125	// Contexto: lojas + canais (derivados em runtime, sem hardcode de loja_id)
126	// ─────────────────────────────────────────────────────────────────────────────
127	
128	/** Loja ativa carregada no contexto do painel. */
129	export interface TvLoja {
130	  id: number;
131	  nome: string;
132	  tipo: string | null;
133	}
134	
135	/** Contexto runtime do painel (lojas + canais) — reusado pelo drill-down. */
136	export interface TvContext {
137	  lojas: TvLoja[];
138	  /** Lojas com venda live (existem em `degust_stores`). */
139	  degustLojaIds: Set<number>;
140	  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
141	  degustCodeToLoja: Map<number, number>;
142	  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
143	  linxLojaIds: number[];
144	  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
145	  factoryLojaId: number | null;
146	}
147	
148	function isFactoryTipo(tipo: string | null): boolean {
149	  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
150	  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
151	}
152	
153	/** Carrega o contexto (exportado para o `useTvStoreDetail` compartilhar cache). */
154	export async function fetchTvContext(): Promise<TvContext> {
155	  const [lojasRes, degustRes] = await Promise.all([
156	    supabase
157	      .from('lojas')
158	      .select('id, nome, tipo')
159	      .eq('ativo', true)
160	      .order('id'),
161	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
162	  ]);
163	  if (lojasRes.error) throw lojasRes.error;
164	  if (degustRes.error) throw degustRes.error;
165	
166	  const lojas: TvLoja[] = lojasRes.data ?? [];
167	  const degustLojaIds = new Set<number>();
168	  const degustCodeToLoja = new Map<number, number>();
169	  for (const row of degustRes.data ?? []) {
170	    degustLojaIds.add(row.loja_id);
171	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
172	  }
173	
174	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
175	  const linxLojaIds = lojas
176	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
177	    .map((l) => l.id);
178	
179	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
180	}
181	
182	// ─────────────────────────────────────────────────────────────────────────────
183	// Vendas live (edge degust-pos-financial / flash-vendas)
184	// ─────────────────────────────────────────────────────────────────────────────
185	
186	/** Contrato da edge `degust-pos-financial` (campos usados pelo painel). */
187	interface DegustPosFinancialResponse {
188	  flash?: Array<{
189	    loja_id: number;
190	    nome_loja: string;
191	    total_vendas: number;
192	    total_cupons: number;
193	    ticket_medio: number;
194	    qtd_produtos: number;
195	    caixa_aberto: boolean;
196	    ultima_atualizacao: string | null;
197	  }>;
198	  /** Breakdown diário via ticket-medio (inclui ontem quando startDate < endDate). */
199	  daily?: Array<{
200	    data: string;       // YYYY-MM-DD
201	    loja_id: number;    // já remapeado pelo edge para loja_id interno
202	    total_faturado: number;
203	  }>;
204	}
205	
206	/**
207	 * Retorno de fetchLiveSales:
208	 * - flash: dados ao vivo de hoje (ou último caixa fechado se madrugada)
209	 * - dailyByLoja: mapa loja_id → data → total_faturado (3 dias)
210	 *   Permite detectar a data real do flash e comparar vs dia anterior correto.
211	 */
212	interface LiveSalesResult {
213	  flash: FlashRow[];
214	  dailyByLoja: Map<number, Map<string, number>>;
215	}
216	
217	async function fetchLiveSales(ctx: TvContext): Promise<LiveSalesResult> {
218	  const today = toIsoDateLocal(new Date());
219	  // Pedir 3 dias para lidar com a virada de meia-noite:
220	  // - hoje: Jun 11 (pode ter dados vazios se lojas ainda fechadas)
221	  // - ontem: Jun 10 (o flash pode mostrar esse dado a madrugada)
222	  // - anteontem: Jun 09 (base de comparação quando flash = Jun 10)
223	  const twoDaysAgo = toIsoDateLocal(addDays(new Date(), -2));
224	
225	  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
226	  const anonKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string;
227	  const session = (await supabase.auth.getSession()).data.session;
228	  const token = session?.access_token ?? anonKey;
229	
230	  const resp = await fetch(`${supabaseUrl}/functions/v1/degust-pos-financial`, {
231	    method: 'POST',
232	    headers: {
233	      'Content-Type': 'application/json',
234	      Authorization: `Bearer ${token}`,
235	      apikey: anonKey,
236	    },
237	    body: JSON.stringify({ startDate: twoDaysAgo, endDate: today }),
238	  });
239	
240	  if (!resp.ok) {
241	    throw new Error(`[tv-dashboard] degust-pos-financial: HTTP ${resp.status}`);
242	  }
243	
244	  const data = (await resp.json()) as DegustPosFinancialResponse;
245	
246	  const flash: FlashRow[] = remapFlashLojaIds(
247	    (data?.flash ?? []).map((f) => ({
248	      loja_id: f.loja_id,
249	      nome_loja: f.nome_loja,
250	      total_vendas: f.total_vendas,
251	      total_cupons: f.total_cupons,
252	      ticket_medio: f.ticket_medio,
253	      caixa_aberto: f.caixa_aberto,
254	      ultima_atualizacao: f.ultima_atualizacao,
255	    })),
256	    ctx.degustCodeToLoja,
257	    ctx.degustLojaIds,
258	  );
259	
260	  // Mapa loja_id → data → total via ticket-medio (dados completos por dia).
261	  // edge function v20 já remapeia codigoLoja → loja_id interno.
262	  const dailyByLoja = new Map<number, Map<string, number>>();
263	  for (const d of data?.daily ?? []) {
264	    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
265	    let byDate = dailyByLoja.get(d.loja_id);
266	    if (!byDate) { byDate = new Map<string, number>(); dailyByLoja.set(d.loja_id, byDate); }
267	    byDate.set(d.data, (byDate.get(d.data) ?? 0) + (d.total_faturado ?? 0));
268	  }
269	
270	  return { flash, dailyByLoja };
271	}
