424	
425	/** Exportado para o `useTvStoreDetail` compartilhar a MESMA query/cache. */
426	export async function fetchStockAlerts(): Promise<StockRow[]> {
427	  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
428	  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
429	  // candidatas hoje). Paginação obrigatória: o PostgREST corta em 1000 linhas
430	  // mesmo com `.limit()` maior — `.order('id')` garante páginas estáveis.
431	  //
432	  // `setor` vai junto no select: a regra do CTO 2026-06-05 (alertas SÓ do
433	  // setor TV_ALERT_SETOR = produtos vendáveis) é aplicada client-side com
434	  // normalização em `buildStockSummary` — a caixa/acento no banco é
435	  // inconsistente ("CÂMARA FRIA" vs "Câmara Fria"), então um `.eq` server-side
436	  // exato deixaria variantes legítimas de "Produtos" passarem/caírem errado.
437	  const data = await fetchAllPages((from, to) =>
438	    supabase
439	      .from('estoque')
440	      .select(
441	        'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo, setor)',
442	      )
443	      .eq('produto_master.ativo', true)
444	      .gt('quantidade_minima', 0)
445	      .or('oculto.is.null,oculto.eq.false')
446	      .order('id')
447	      .range(from, to),
448	  );
449	  return data.map((row) => ({
450	    loja_id: row.loja_id,
451	    quantidade_atual: row.quantidade_atual,
452	    quantidade_minima: row.quantidade_minima,
453	    produtoNome: row.produto_master?.nome ?? '(sem nome)',
454	    setor: row.produto_master?.setor ?? null,
455	  }));
456	}
