552	async function fetchPerdasAggregates(
553	  period: TvPeriod,
554	): Promise<PeriodedAggregates<PerdasByLoja>> {
555	  const now = new Date();
556	  const [current, previous] = await Promise.all([
557	    loadPerdasRange(periodRange(period, now)),
558	    loadPerdasRange(previousPeriodRange(period, now)),
559	  ]);
560	  return { current, previous };
561	}
