663	
664	const EMPTY_PERDAS_AGG: PerdasAggregate = { valor: 0, itens: 0 };
665	
666	/** Monta o resumo de perdas de UMA unidade a partir dos agregados. */
667	function perdasSummaryFor(
668	  agg: PeriodedAggregates<PerdasByLoja> | undefined,
669	  lojaId: number,
670	): TvPerdasSummary {
671	  const cur = agg?.current.byLoja.get(lojaId) ?? EMPTY_PERDAS_AGG;
672	  const prev = agg?.previous.byLoja.get(lojaId);
673	  return {
674	    valor: cur.valor,
675	    itens: cur.itens,
676	    deltaPct: relativeDelta(cur.valor, prev?.valor ?? null),
677	  };
678	}
679	
680	const EMPTY_MARKETING_AGG: MarketingAggregate = { valor: 0, acoes: 0 };
681	
682	/** Monta o resumo de marketing de UMA unidade a partir dos agregados. */
683	function marketingSummaryFor(
684	  agg: PeriodedAggregates<MarketingByLoja> | undefined,
685	  lojaId: number,
686	): TvMarketingSummary {
687	  const cur = agg?.current.byLoja.get(lojaId) ?? EMPTY_MARKETING_AGG;
688	  const prev = agg?.previous.byLoja.get(lojaId);
689	  return {
690	    valor: cur.valor,
691	    acoes: cur.acoes,
692	    deltaPct: relativeDelta(cur.valor, prev?.valor ?? null),
693	  };
694	}
695	
696	/**
697	 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
698	 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
699	 * `freshness`). Vendas live re-buscam a cada 60s; o resto a
700	 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
701	 *
702	 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
703	 *   seus comparativos. Vendas dos cards são SEMPRE de hoje (+ % vs ontem).
704	 */
705	export function useTvDashboardData(period: TvPeriod = 'today'): TvDashboardData {
706	  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
707	  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
708	  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
709	  const tick = useMinuteClock();
710	
711	  const ctxQuery = useQuery({
712	    queryKey: tvDashboardKeys.context(),
713	    queryFn: fetchTvContext,
714	    staleTime: TV_QUERY_INTERVALS.slowMs,
